using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions { TypeInfoResolver = new DefaultJsonTypeInfoResolver() };

// 1️⃣  Strongly-typed retrieval — returns JsonTypeInfo<Person> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip using the typed info to prove it works.
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Person? p = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Round-trip: {p}");

// 2️⃣  Probe without throwing — TryGetTypeInfo returns false if unavailable.
//     Use a resolver that resolves nothing to simulate "not available".
var limited = new JsonSerializerOptions { TypeInfoResolver = new EmptyResolver() };

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"Found metadata: {info!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata for Person is NOT available (no exception thrown).");
}

// Also show the positive path with TryGetTypeInfo:
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2))
{
    Console.WriteLine($"TryGetTypeInfo succeeded: {info2!.Type.Name}");
}

// --- Types ---------------------------------------------------------------

record Person(string Name, int Age);

/// <summary>A resolver that deliberately resolves nothing.</summary>
sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

